-- Never let an older application issue prefixes assigned after this migration.
SELECT setval('clinlims.sample_cug_prefix_seq', greatest(last_value,
  coalesce((SELECT max(prefix) FROM clinlims.sample_cug_prefix), last_value)),
  is_called OR EXISTS(SELECT 1 FROM clinlims.sample_cug_prefix)) FROM clinlims.sample_cug_prefix_seq;
DROP TRIGGER record_sample_item_cug_prefix ON clinlims.sample_item;
DROP TRIGGER record_reservation_cug_prefix ON clinlims.sample_cug_reservation;
DROP FUNCTION clinlims.record_cug_prefix();
DROP TRIGGER merge_cug_prefix_range ON clinlims.sample_cug_prefix;
DROP FUNCTION clinlims.merge_cug_prefix_range();
DROP TRIGGER lock_cug_prefix_counter ON clinlims.sample_cug_prefix;
DROP FUNCTION clinlims.lock_cug_prefix_counter();
DROP FUNCTION clinlims.cug_numeric_prefix(text);
